#!/usr/bin/env python3
# Answer-agnostic live-oracle driver. Connects to the challenge console on 4562,
# dumps the banner, sends newline-separated commands (argv), prints every byte back.
import socket, time, threading, sys, re

HOST, PORT = "127.0.0.1", 4562

class Reader:
    def __init__(self, s):
        self.s=s; self.buf=bytearray(); self.lock=threading.Lock(); self.alive=True
        threading.Thread(target=self.run, daemon=True).start()
    def run(self):
        while self.alive:
            try: d=self.s.recv(65536)
            except socket.timeout: continue
            except Exception: break
            if not d: self.alive=False; break
            with self.lock: self.buf.extend(d)
    def snap(self):
        with self.lock: return bytes(self.buf)

def pr(b):
    return ''.join('\n' if x==10 else (chr(x) if 32<=x<127 else f'<{x:02x}>') for x in b)

def main():
    banner_to=float(sys.argv[1]); cmd_to=float(sys.argv[2]); cmds=sys.argv[3:]
    s=socket.create_connection((HOST,PORT),timeout=10); s.settimeout(1.0)
    r=Reader(s)
    time.sleep(banner_to)
    snap=r.snap(); base=len(snap)
    print(f"=== BANNER ({len(snap)}B) ===\n{pr(snap)}\n--- repr ---\n{snap!r}",flush=True)
    for c in cmds:
        if c.startswith("WAIT:"):
            time.sleep(float(c[5:]))
        else:
            print(f"\n>>> {c!r}",flush=True)
            s.sendall((c+"\n").encode())
            time.sleep(cmd_to)
        snap=r.snap(); new=snap[base:]; base=len(snap)
        print(f"<<< ({len(new)}B)\n{pr(new)}\n--- repr ---\n{new!r}",flush=True)
    time.sleep(1.5)
    snap=r.snap(); new=snap[base:]
    if new:
        print(f"\n=== DRAIN ({len(new)}B) ===\n{pr(new)}\n--- repr ---\n{new!r}",flush=True)
    s.close()

main()

