#!/usr/bin/env python3
import sys
from capstone import Cs, CS_ARCH_X86, CS_MODE_64
from elftools.elf.elffile import ELFFile

path="/home/vboxuser/rev-analysis/extract/csirac/csirac.pd_linux"
f=open(path,'rb')
elf=ELFFile(f)
text=None
for s in elf.iter_sections():
    if s.name=='.text':
        text=s
        break
data=text.data()
base=text['sh_addr']
print(f".text addr={base:#x} size={len(data)}")
md=Cs(CS_ARCH_X86, CS_MODE_64)
md.detail=True
# find instructions with immediates of interest
targets={0x8d,0x4f,95,94,32,0x5f,3972,42,256,0x9a3f}
hits={t:[] for t in targets}
insns=list(md.disasm(data, base))
print("total insns", len(insns))
for ins in insns:
    for op in ins.operands:
        if op.type==2: # imm
            v=op.imm & 0xffffffffffffffff
            for t in targets:
                if v==t:
                    hits[t].append(ins.address)
for t in sorted(targets):
    hs=hits[t]
    print(f"imm {t} (0x{t:x}): {len(hs)} hits; first few: {[hex(a) for a in hs[:12]]}")

